let CURR_LANG = {};

function getTranslation(str, lang) {
  if (!str || !lang || lang === 'en') return str;
  const cleanStr = str.replace(/ /g, ' ').replace(/\s+/g, ' ').trim();
  if (!cleanStr) return str;

  const langDict = I18N[lang];
  const fbLang = LANG_FALLBACKS[lang];
  const fbDict = fbLang ? I18N[fbLang] : null;

  // 1. Direct exact matches
  if (langDict && langDict[cleanStr]) return langDict[cleanStr];
  if (langDict && langDict[str]) return langDict[str];
  if (fbDict && fbDict[cleanStr]) return fbDict[cleanStr];
  if (fbDict && fbDict[str]) return fbDict[str];

  // 2. Strip emoji / bullet / symbol prefixes
  const emojiMatch = cleanStr.match(/^([\p{Extended_Pictographic}\p{Emoji}‍️\s•·|–—➔✓~]+)\s*(.*)$/u);
  if (emojiMatch) {
    const symbol = emojiMatch[1].trim();
    const rest = emojiMatch[2].trim();
    if (rest) {
      if (langDict && langDict[rest]) return symbol + ' ' + langDict[rest];
      if (fbDict && fbDict[rest]) return symbol + ' ' + fbDict[rest];
    }
  }

  // 3. Dynamic regex patterns with numbers
  const m1 = cleanStr.match(/^Leave now! Travel time (\d+) min\.$/);
  if (m1) {
    const tmpl = getTranslation("Leave now! Travel time {n} min.", lang);
    return tmpl.replace('{n}', m1[1]);
  }
  const m2 = cleanStr.match(/^Get ready — leave in ~(\d+) min\.$/);
  if (m2) {
    const tmpl = getTranslation("Get ready — leave in ~{n} min.", lang);
    return tmpl.replace('{n}', m2[1]);
  }
  const m3 = cleanStr.match(/^Relax at home — leave in ~(\d+) min\.$/);
  if (m3) {
    const tmpl = getTranslation("Relax at home — leave in ~{n} min.", lang);
    return tmpl.replace('{n}', m3[1]);
  }
  const m4 = cleanStr.match(/^Proceed to Counter (\d+) now$/);
  if (m4) {
    const tmpl = getTranslation("Proceed to Counter {n} now", lang);
    return tmpl.replace('{n}', m4[1]);
  }
  const m5 = cleanStr.match(/^(\d+)\s+Tokens Ahead$/i);
  if (m5) {
    return m5[1] + ' ' + getTranslation("Tokens Ahead", lang);
  }
  const m6 = cleanStr.match(/^(\d+)m\s+Wait now$/i);
  if (m6) {
    const minSuffix = (lang === 'hi' ? 'मि.' : lang === 'gu' ? 'મિ.' : 'm');
    return m6[1] + minSuffix + ' ' + getTranslation("Wait now", lang);
  }

  return str;
}

const T = i => {
  const orig = STR[i] || '';
  return getTranslation(orig, S.lang || 'en');
};
const tt = (i, v={}) => T(i).replace(/\{(\w+)\}/g, (m,k) => v[k] ?? m);

function applyLang() {
  const lang = S.lang || 'en';

  // 1. Full-page text node traversal
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
    acceptNode: function(node) {
      const p = node.parentElement;
      if (!p) return NodeFilter.FILTER_REJECT;
      const tag = p.tagName.toLowerCase();
      if (tag === 'script' || tag === 'style') return NodeFilter.FILTER_REJECT;
      if (!node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }
  });

  let node;
  while (node = walker.nextNode()) {
    if (node._origText === undefined) {
      node._origText = node.nodeValue;
    }
    const orig = node._origText;
    const cleanOrig = orig.replace(/ /g, ' ').replace(/\s+/g, ' ').trim();
    if (!cleanOrig) continue;

    if (lang === 'en') {
      if (node.nodeValue !== orig) node.nodeValue = orig;
    } else {
      const trans = getTranslation(cleanOrig, lang);
      if (trans && trans !== cleanOrig) {
        const lead = (orig.match(/^(\s*)/) || [''])[0];
        const trail = (orig.match(/(\s*)$/) || [''])[0];
        const res = lead + trans + trail;
        if (node.nodeValue !== res) node.nodeValue = res;
      }
    }
  }

  // 2. Input and textarea placeholders
  document.querySelectorAll('input[placeholder], textarea[placeholder]').forEach(inp => {
    if (inp._origPlaceholder === undefined) {
      inp._origPlaceholder = inp.placeholder;
    }
    if (lang === 'en') {
      inp.placeholder = inp._origPlaceholder;
    } else {
      const trans = getTranslation(inp._origPlaceholder, lang);
      if (trans) inp.placeholder = trans;
    }
  });

  // 3. Dropdown placeholder options
  ['#of', '#ao', '#sv'].forEach(id => {
    const sel = document.querySelector(id);
    if (sel && sel.options && sel.options[0] && sel.options[0].disabled) {
      const opt = sel.options[0];
      if (opt._origText === undefined) opt._origText = opt.textContent;
      opt.textContent = (lang === 'en') ? opt._origText : getTranslation(opt._origText, lang);
    }
  });

  // 4. Translate #est if office selected
  const estEl = document.querySelector('#est');
  if (estEl && S.sel) {
    if (lang !== 'en') {
      const w = newWait(S.sel);
      const est = Math.round(w);
      const margin = Math.max(2, Math.round(est * .15));
      const callT = fmt(getEngineTime() + est);
      const prefix = getTranslation("New token now → est. wait", lang);
      const minText = lang === 'hi' ? 'मिनट' : lang === 'gu' ? 'મિનિટ' : 'min';
      const callPrefix = getTranslation("call time ≈", lang);
      estEl.innerHTML = `${prefix} <b>${est} ${minText}</b> (±${margin}) · ${callPrefix} <b>${callT}</b>`;
    }
  }

  // 5. Chatbot sample questions
  const chips = document.querySelector('#chips');
  if (chips) {
    const qs = [
      "Which documents do I need for a driving licence?",
      "When should I leave home?",
      "Which office is fastest for me?"
    ];
    chips.innerHTML = qs.map(q => {
      const tq = getTranslation(q, lang);
      return `<button class="btn s g" onclick="ask('${tq.replace(/'/g, "\\'")}')">${tq}</button>`;
    }).join('');
  }

  // 6. Translate document title
  if (lang === 'en') {
    document.title = "QueueLess – Smart Government Office Queues";
  } else {
    document.title = "QueueLess – " + getTranslation("Smart Government Office Queues", lang);
  }

  // 7. Update TTS button state
  updateTtsBtn(window.speechSynthesis && window.speechSynthesis.speaking);
}

function setLang(c) {
  const lEntry = LANGS.find(x => x[0] === c) || ['en','English','English'];
  const [code, nm, nat] = lEntry;
  S.lang = code;
  try { localStorage.setItem('ql_lang', code); } catch(e){}
  document.documentElement.lang = code;
  document.body.dir = ['ur', 'ks', 'sd'].includes(code) ? 'rtl' : 'ltr';
  if (document.querySelector('#lg')) document.querySelector('#lg').value = code;

  draw();
  applyLang();

  const msg = code === 'en'
    ? '🌐 English — Page language updated.'
    : `🌐 ${nat} (${nm}) — ${getTranslation("Page translated successfully.", code)}`;
  say(msg);
}

function speakCurrentPage() {
  if (!('speechSynthesis' in window)) {
    say('⚠️ Speech synthesis is not supported on this browser.');
    return;
  }
  if (window.speechSynthesis.speaking) {
    window.speechSynthesis.cancel();
    updateTtsBtn(false);
    say('⏹️ Audio stopped.');
    return;
  }

  const lang = S.lang || 'en';
  const tag = LANG_SPEECH_TAGS[lang] || 'en-IN';
  let speechText = '';
  const myTokenId = S.mine && S.mine.length ? S.mine[S.mine.length - 1] : null;
  const token = myTokenId && window.Engine ? window.Engine.getToken(myTokenId) : null;

  if (token && (token.status === 'ISSUED' || token.status === 'RESERVED' || token.status === 'CALLED')) {
    const etaM = Math.ceil((token.etaSeconds || 0) / 60);
    const ahead = token.tokensAhead || 0;
    if (token.status === 'CALLED') {
      speechText = getTranslation("It's your turn!", lang) + ". " +
                   getTranslation("Token Number", lang) + " " + token.tokenNumber + ". " +
                   getTranslation("Please proceed to the counter.", lang);
    } else {
      speechText = getTranslation("Token Number", lang) + " " + token.tokenNumber + ". " +
                   ahead + " " + getTranslation("Tokens Ahead", lang) + ". " +
                   getTranslation("Est. Wait", lang) + " " + etaM + " " + (lang === 'hi' ? 'मिनट' : 'minutes') + ".";
    }
  } else {
    speechText = getTranslation("Welcome to QueueLess", lang) + ". " +
                 getTranslation("Delivering Token services to citizens in a timely, accessible and reliable manner", lang) + ".";
  }

  const utt = new SpeechSynthesisUtterance(speechText);
  utt.lang = tag;
  utt.rate = 0.95;
  utt.pitch = 1.0;

  try {
    const voices = window.speechSynthesis.getVoices();
    const matched = voices.find(v => v.lang.startsWith(tag.slice(0, 2)) || v.lang === tag);
    if (matched) utt.voice = matched;
  } catch(e){}

  utt.onstart = () => {
    updateTtsBtn(true);
    say('🔊 ' + getTranslation("Speaking...", lang));
  };
  utt.onend = () => { updateTtsBtn(false); };
  utt.onerror = () => { updateTtsBtn(false); };

  window.speechSynthesis.speak(utt);
}

function updateTtsBtn(isPlaying) {
  const btn = document.querySelector('#btn-tts');
  if (!btn) return;
  const lang = S.lang || 'en';
  if (isPlaying) {
    btn.innerHTML = '⏹️ ' + (lang === 'hi' ? 'रोकें' : lang === 'ta' ? 'நிறுத்து' : lang === 'gu' ? 'રોકો' : 'Stop');
    btn.style.background = 'var(--bad)';
    btn.style.color = '#fff';
  } else {
    btn.innerHTML = '🔊 ' + (lang === 'hi' ? 'सुनें' : lang === 'ta' ? 'கேளுங்கள்' : lang === 'gu' ? 'સાંભળો' : 'Listen');
    btn.style.background = '';
    btn.style.color = '';
  }
}

// Expose globally
window.setLang = setLang;
window.applyLang = applyLang;
window.speakCurrentPage = speakCurrentPage;
window.getTranslation = getTranslation;

// Populate language select options
if (document.querySelector('#lg')) {
  document.querySelector('#lg').innerHTML = LANGS.map(l => `<option value="${l[0]}">${l[2]} – ${l[1]}</option>`).join('');
}
